function ribbon(offsetA,offsetB,material,raise=0){const verts=[],idx=[];for(let i=0;i<=N;i++){const k=Math.min(i,N-1),j=i===N?(closed?0:N-1):i,p=samples[j],t=tangents[j],nx=t.z,nz=-t.x,prev=tangents[mod(j-4,N)],next=tangents[mod(j+4,N)],curvature=angleDiff(Math.atan2(next.x,next.z),Math.atan2(prev.x,prev.z)),bank=clamp(curvature*5,-1,1)*settings.bank*Math.PI/180;for(const off of[offsetA,offsetB])verts.push(p.x+nx*off,p.y+raise+Math.sin(bank)*off,p.z+nz*off);if(i<N){let a=i*2;idx.push(a,a+2,a+1,a+1,a+2,a+3)}}let g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(verts,3));g.setIndex(idx);g.computeVertexNormals();let m=new T.Mesh(g,material);m.receiveShadow=true;world.add(m);return m}
