 if(['gt','prototype','rally','drift','stock'].includes(v.type)){meshBox(g,w*.92,.1,.4,0,1.35+lift,-l*.42,dark);for(let s of[-1,1])meshBox(g,.08,.5,.15,s*w*.3,1.08+lift,-l*.42,dark)}
 if(v.type==='police'){meshBox(g,w*.65,.18,.3,0,1.65,0,mat(0x5375d4));meshBox(g,w*.32,.19,.31,w*.16,1.65,0,mat(0xec5551))}
