 for(let [x,z]of wheelPos){const wheel=new T.Mesh(wheelGeo,dark);wheel.rotation.z=Math.PI/2;wheel.position.set(x,radius,z);wheel.castShadow=true;g.add(wheel);wheels.push(wheel)}
