function resize(){let r=host.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();let b=$('board').getBoundingClientRect();if(b.width){$('board').width=Math.round(b.width*devicePixelRatio);$('board').height=Math.round(b.height*devicePixelRatio)}boardDirty=true}
