function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3600)}
function snapshot(){history.push(JSON.stringify(settings));if(history.length>30)history.shift()}
function syncUI(){for(let k of['width','hills','bank','scale','biome','surface','mode','laps','ai','difficulty'])$(k).value=settings[k];for(let k of['barriers','scenery','collisions','slipstream'])$(k).checked=settings[k];$('trackName').value=settings.name;updateOutputs()}
function updateOutputs(){for(let[k,suffix]of[['width',' m'],['hills',' m'],['bank','°'],['scale','%'],['ai','']])$(k+'Out').textContent=$(k).value+suffix}
function setTool(value){tool=value;$('board').hidden=value==='view';for(let [id,t]of[['drawBtn','draw'],['dotsBtn','dots'],['viewBtn','view']])$(id).classList.toggle('active',value===t);$('editorHint').textContent=value==='draw'?'Draw your circuit in one stroke. It closes automatically.':value==='dots'?'Drag nodes. Tap to add. Double-click to remove.':'Drag to orbit. Scroll to get closer.';resize();boardDirty=true}
function drawBoard(){let c=$('board'),ctx=c.getContext('2d'),W=c.width,H=c.height;if(!W||!H)return;ctx.fillStyle='#223126';ctx.fillRect(0,0,W,H);if(traceImage){ctx.globalAlpha=.32;let sc=Math.min(W/traceImage.width,H/traceImage.height);ctx.drawImage(traceImage,(W-traceImage.width*sc)/2,(H-traceImage.height*sc)/2,traceImage.width*sc,traceImage.height*sc);ctx.globalAlpha=1}ctx.strokeStyle='#aabb9912';ctx.lineWidth=1;for(let x=0;x<W;x+=32*devicePixelRatio){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=32*devicePixelRatio){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}const box=boardBox(W,H);let pts=drawing?raw:settings.points;if(samples.length&&!drawing){ctx.beginPath();samples.forEach((p,i)=>{let x=box.x+(p.x/(1000*settings.scale/100)+.5)*box.s,y=box.y+(p.z/(1000*settings.scale/100)+.5)*box.s;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});if(closed)ctx.closePath();ctx.strokeStyle='#b0b99b';ctx.lineWidth=(settings.width+4)/(1000*settings.scale/100)*box.s;ctx.lineJoin='round';ctx.stroke();ctx.strokeStyle='#4b5950';ctx.lineWidth=settings.width/(1000*settings.scale/100)*box.s;ctx.stroke()}if(drawing){ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(box.x+p.x*box.s,box.y+p.y*box.s):ctx.moveTo(box.x+p.x*box.s,box.y+p.y*box.s));ctx.strokeStyle='#d8f36a';ctx.lineWidth=3*devicePixelRatio;ctx.stroke()}else if(tool==='dots'){pts.forEach((p,i)=>{let x=box.x+p.x*box.s,y=box.y+p.y*box.s;ctx.fillStyle=i===0?'#d8f36a':'#e7edd8';ctx.beginPath();ctx.arc(x,y,5*devicePixelRatio,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dee8cd';ctx.font=`${10*devicePixelRatio}px Arial`;ctx.fillText(i+1,x+8*devicePixelRatio,y-7*devicePixelRatio)})}ctx.fillStyle='#c3d1b4';ctx.font=`${10*devicePixelRatio}px Arial`;ctx.fillText('N ↑',22*devicePixelRatio,70*devicePixelRatio);boardDirty=false}
function boardBox(W,H){let s=Math.min(W*.91,H*.70);return{s,x:(W-s)/2,y:(H-s)/2-30*devicePixelRatio}}
function boardPoint(e){const c=$('board'),r=c.getBoundingClientRect(),b=boardBox(c.width,c.height);return{x:clamp(((e.clientX-r.left)*devicePixelRatio-b.x)/b.s,.015,.985),y:clamp(((e.clientY-r.top)*devicePixelRatio-b.y)/b.s,.015,.985)}}
$('board').addEventListener('pointerdown',e=>{$('board').setPointerCapture(e.pointerId);snapshot();const p=boardPoint(e);if(tool==='draw'){drawing=true;raw=[p]}else{boardDrag=settings.points.findIndex(q=>Math.hypot(q.x-p.x,q.y-p.y)<.025);if(boardDrag<0){let best=Infinity,at=settings.points.length;for(let i=0;i<settings.points.length;i++){let a=settings.points[i],b=settings.points[(i+1)%settings.points.length],d=Math.hypot(p.x-(a.x+b.x)/2,p.y-(a.y+b.y)/2);if(d<best){best=d;at=i+1}}settings.points.splice(at,0,p);boardDrag=at;buildTrack()}}boardDirty=true});
$('board').addEventListener('pointermove',e=>{const p=boardPoint(e);if(drawing){if(!raw.length||Math.hypot(p.x-raw.at(-1).x,p.y-raw.at(-1).y)>.004)raw.push(p);boardDirty=true}else if(boardDrag>=0){settings.points[boardDrag]=p;buildTrack()}});
function finishDraw(){if(drawing){drawing=false;let pts=simplify(raw,.035);if(pts.length>=3){settings.points=pts;daily=false;buildTrack()}else toast('Draw a longer shape with at least three points.')}boardDrag=-1;boardDirty=true}
$('board').addEventListener('pointerup',finishDraw);$('board').addEventListener('pointercancel',finishDraw);
$('board').addEventListener('dblclick',e=>{if(tool!=='dots')return;let p=boardPoint(e),i=settings.points.findIndex(q=>Math.hypot(q.x-p.x,q.y-p.y)<.03);if(i>=0&&settings.points.length>3){snapshot();settings.points.splice(i,1);buildTrack()}});
renderer.domElement.addEventListener('pointerdown',e=>{if(driving)return;orbitDrag=true;previousPointer={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)});
