function drawMinimap(){const c=$('minimap'),ctx=c.getContext('2d'),W=c.width,H=c.height;ctx.clearRect(0,0,W,H);if(!samples.length)return;let size=bounds.getSize(new T.Vector3()),s=Math.min((W-25)/Math.max(1,size.x),(H-25)/Math.max(1,size.z)),ox=(W-size.x*s)/2,oy=(H-size.z*s)/2;const point=p=>({x:ox+(p.x-bounds.min.x)*s,y:oy+(p.z-bounds.min.z)*s});ctx.beginPath();samples.forEach((p,i)=>{let q=point(p);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});if(closed)ctx.closePath();ctx.strokeStyle='#bbc9ad';ctx.lineWidth=3;ctx.stroke();for(let c of[...bots,player]){let q=point(c);ctx.fillStyle=c===player?'#d8f36a':'#df927d';ctx.beginPath();ctx.arc(q.x,q.y,c===player?4:2.7,0,Math.PI*2);ctx.fill()}}
function updateHUD(){let speed=Math.round(Math.hypot(player.vx,player.vz)*3.6);$('speed').textContent=speed;$('engineReadout').hidden=selected!==1;$('engineReadout').textContent='GEAR '+f1State.gear+' · '+Math.round(f1State.rpm).toLocaleString()+' RPM';$('timer').textContent=time(lapTime);$('lapLabel').textContent=closed?'LAP '+lap+(settings.mode==='race'?' / '+settings.laps:''):(Math.min(100,Math.floor(player.index/N*100)))+'%';$('revbar').style.width=clamp(speed/(player.v.top*3.6)*140,0,140)+'px';if(frameId%12===0){const racers=[{name:'You',distance:player.progress,you:true},...bots].sort((a,b)=>b.distance-a.distance);$('leaderboard').innerHTML=racers.slice(0,7).map((r,i)=>`<div class="positionrow ${r.you?'you':''}"><span>${i+1} &nbsp;${r.name}</span><span>${r.you?'●':r.finished?'FIN':' '}</span></div>`).join('');drawMinimap()}}
function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-lastTime)/1000,.05)||.016;lastTime=now;frameId++;
 if(driving&&player){accumulator+=dt;while(accumulator>=1/60){tick(1/60);accumulator-=1/60}let p=player,prev=p.previous||p,alpha=clamp(accumulator*60,0,1),rx=prev.x+(p.x-prev.x)*alpha,ry=prev.y+(p.y-prev.y)*alpha,rz=prev.z+(p.z-prev.z)*alpha,rh=prev.heading+angleDiff(p.heading,prev.heading)*alpha;p.mesh.position.set(rx,ry+.08,rz);p.mesh.rotation.y=rh;let forward=new T.Vector3(Math.sin(rh),0,Math.cos(rh)),target=new T.Vector3(rx,ry+1.1,rz),desired;if(camMode===0){desired=target.clone().addScaledVector(forward,-10-p.v.length*.7);desired.y+=5.5;target.addScaledVector(forward,10)}else if(camMode===1){desired=target.clone().addScaledVector(forward,p.v.length*.25);desired.y+=.5;target.addScaledVector(forward,30)}else{desired=target.clone().add(new T.Vector3(0,100,-25));target.addScaledVector(forward,8)}camera.position.copy(desired);camera.lookAt(target);updateHUD();}
 else{if(!orbitDrag&&tool==='view')viewAngle+=dt*.018;let size=bounds?bounds.getSize(new T.Vector3()).length():800,center=bounds?bounds.getCenter(new T.Vector3()):new T.Vector3(),radius=size*viewZoom*.7;camera.position.set(center.x+Math.sin(viewAngle)*radius*Math.cos(viewTilt),center.y+radius*Math.sin(viewTilt),center.z+Math.cos(viewAngle)*radius*Math.cos(viewTilt));camera.lookAt(center);if(tool!=='view'&&boardDirty)drawBoard()}
 renderer.render(scene,camera)
}
window.addEventListener('beforeunload',()=>{if(driving)write('og-stats',stats)});
syncUI();buildTrack();resize();requestAnimationFrame(animate);
